import enum

class PlayerState(enum.Enum):
    X = 'X'
    O = 'O'
    EMPTY = ' '

class GomokuGame:
    FIVE_IN_A_ROW = 5
    DIRECTIONS = [(0, 1), (1, 0), (1, 1), (1, -1)]

    def __init__(self, board_size):
        self._board_size = board_size
        self._board = [[PlayerState.EMPTY for _ in range(board_size)] for _ in range(board_size)]
        self._current_player = PlayerState.X

    @property
    def board_size(self):
        return self._board_size

    @property
    def board(self):
        return [row[:] for row in self._board]

    @property
    def current_player(self):
        return self._current_player.value

    def make_move(self, row, col):
        if self._is_valid_move(row, col):
            self._place_mark(row, col)
            self._switch_player()
            return True
        return False

    def _is_valid_move(self, row, col):
        return self._board[row][col] == PlayerState.EMPTY

    def _place_mark(self, row, col):
        self._board[row][col] = self._current_player

    def _switch_player(self):
        self._current_player = PlayerState.O if self._current_player == PlayerState.X else PlayerState.X

    def check_winner(self):
        return self._find_winner_in_board()

    def _find_winner_in_board(self):
        for row in range(self._board_size):
            for col in range(self._board_size):
                if self._board[row][col] != PlayerState.EMPTY:
                    winner = self._check_directions_at(row, col)
                    if winner is not None:
                        return winner
        return None

    def _check_directions_at(self, row, col):
        for direction in self.DIRECTIONS:
            if self._check_five_in_a_row(row, col, direction):
                return self._board[row][col].value
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        count = self._count_consecutive_marks(row, col, dx, dy)
        return count >= self.FIVE_IN_A_ROW

    def _count_consecutive_marks(self, row, col, dx, dy):
        symbol = self._board[row][col]
        count = 1
        for i in range(1, self.FIVE_IN_A_ROW):
            new_row = row + dx * i
            new_col = col + dy * i
            if not self._is_within_bounds(new_row, new_col):
                return count
            if self._board[new_row][new_col] != symbol:
                return count
            count += 1
        return count

    def _is_within_bounds(self, row, col):
        return 0 <= row < self._board_size and 0 <= col < self._board_size
